<?php
require_once __DIR__.'/test_support.php';['db'=>$db,'fixture'=>$f]=erpTestFixture();
require_once __DIR__.'/learning_sharing_fixture.php';$f=learningSharingFixture($db,$f);
if(is_file(__DIR__.'/../includes/learning_content.php'))require_once __DIR__.'/../includes/learning_content.php';
erpCheck(function_exists('learningCanView'),'Learning policy is available');
$actors=[];foreach($f['ids'] as $name=>$id)$actors[$name]=learningActor($db,$id);
$owner=$actors['teacher'];$co=$actors['co_teacher'];$admin=$actors['school_admin'];$student=$actors['student_login'];
$q=['school_id'=>1,'class_id'=>$f['class'],'subject_id'=>$f['subject'],'created_by_user_id'=>$owner['id'],'visibility'=>'private','archived_at'=>null];
foreach(['teacher'=>true,'co_teacher'=>true,'school_admin'=>true,'unrelated_teacher'=>false,'student_login'=>false,'other_student_login'=>false,'other_admin'=>false] as $role=>$allowed)erpEqual(learningCanView($db,$actors[$role],$q),$allowed,'Private read '.$role);
foreach(['teacher'=>true,'co_teacher'=>false,'school_admin'=>false,'unrelated_teacher'=>false] as $role=>$allowed)erpEqual(learningCanEdit($db,$actors[$role],$q),$allowed,'Creator edit '.$role);
$q['visibility']='public';foreach(['teacher','co_teacher','school_admin','unrelated_teacher','student_login'] as $name)erpCheck(learningCanView($db,$actors[$name],$q),'School public '.$name);
erpEqual(learningCanView($db,$actors['other_admin'],$q),false,'Public is school only');erpEqual(learningCanView($db,$actors['other_student_login'],$q),false,'Foreign student denied');
$legacy=$q;$legacy['created_by_user_id']=null;erpEqual(learningCanEdit($db,$admin,$legacy),false,'Unknown creator read-only');
$ownAdmin=$q;$ownAdmin['created_by_user_id']=$admin['id'];erpCheck(learningCanEdit($db,$admin,$ownAdmin),'Admin manages own content');
$preview=learningActor($db,$f['ids']['super_admin'],1,true);erpEqual(learningCanEdit($db,$preview,$q),false,'Preview read-only');
erpEqual(learningCanCreate($db,$actors['principal'],$f['class'],$f['subject']),false,'Principal gains no create');
$sharedScope=learningCatalogScope($db,1,$f['class'],$f['subject'])['shared'];$shared=$sharedScope+['created_by_user_id'=>null,'visibility'=>'public','archived_at'=>null];
erpCheck(learningCanView($db,$student,$shared),'Shared readable by enrolled student');erpEqual(learningCanEdit($db,$owner,$shared),false,'Shared read-only');erpCheck(learningCanEdit($db,$actors['super_admin'],$shared),'Shared managed by super admin');
$shared['visibility']='private';erpEqual(learningCanView($db,$student,$shared),false,'Global draft private');erpCheck(learningCanView($db,$actors['super_admin'],$shared),'Super admin draft read');
$db->prepare('INSERT INTO questions(school_id,class_id,subject_id,chapter,question_text,created_by_user_id,visibility) VALUES(1,?,?,?, ?,?,?)')->execute([$f['class'],$f['subject'],'Sets','Hidden unique lesson',$owner['id'],'private']);$id=(int)$db->lastInsertId();
erpEqual(count(learningContentList($db,$student,'questions',['search'=>'Hidden unique'])),0,'Private search/count excluded');
erpReject(fn()=>learningContentRecord($db,$actors['other_admin'],'questions',$id),'Foreign direct ID generic denial');
erpEqual(learningContentRecord($db,$co,'questions',$id)['can_edit'],false,'Co-teacher row read-only');
$db->prepare('UPDATE class_subjects SET teacher_id=? WHERE class_id=? AND subject_id=?')->execute([$co['id'],$f['class'],$f['subject']]);
erpCheck(learningCanView($db,$owner,$q),'Creator reads after losing assignment');erpEqual(learningCanEdit($db,$owner,$q),false,'Creator cannot edit after losing assignment');
$db->exec('UPDATE users SET status=0 WHERE id='.$owner['id']);erpEqual(learningCanView($db,$owner,$q),false,'Disabled account cannot read');erpReject(fn()=>learningActor($db,$owner['id']),'Disabled actor rejected');
erpReject(fn()=>learningActor($db,$admin['id'],$f['otherSchool']),'School context cannot be forged');
erpReject(fn()=>learningContentList($db,$student,'users',[]),'Reject invalid kind');erpReject(fn()=>learningContentList($db,$student,'questions',['class_id'=>[$f['class']]]),'Reject array ID');
echo 'Learning content policy checks passed: '.$GLOBALS['erp_checks'].PHP_EOL;
